{
  "labels": [
    {
      "i": 0,
      "speaker": "bot",
      "text": "Hello SK जी आपको Kurkure मसाला की requirement है ना?"
    },
    {
      "i": 1,
      "speaker": "caller",
      "text": "Hello SKG."
    },
    {
      "i": 2,
      "speaker": "caller",
      "text": "हाँ।"
    },
    {
      "i": 3,
      "speaker": "bot",
      "text": "आप जिस seller को call कर रहे थे वो available नहीं है और मैं IndiaMART से बोल रही हूं।"
    },
    {
      "i": 4,
      "speaker": "bot",
      "text": "आपको कितने kilograms चाहिए?"
    },
    {
      "i": 5,
      "speaker": "caller",
      "text": "मेरे को एक kilogram चाहिए।"
    },
    {
      "i": 6,
      "speaker": "caller",
      "text": "ठीक है।"
    },
    {
      "i": 7,
      "speaker": "caller",
      "text": "और और एक मसाला चाहिए मगर मैं order कैसे करूं उसको?"
    },
    {
      "i": 8,
      "speaker": "bot",
      "text": "ठीक है।"
    },
    {
      "i": 9,
      "speaker": "bot",
      "text": "आप पूरी list seller को भेज दीजिएगा वो आपकी मदद करेंगे लेकिन best seller से connect करने के लिए details confirm कर दीजिए please।"
    },
    {
      "i": 10,
      "speaker": "bot",
      "text": "बताइए flavor में क्या prefer करेंगे tangy tomato, magic masala या कोई और?"
    },
    {
      "i": 11,
      "speaker": "caller",
      "text": "जो मैंने अभी देखा जहां से मैंने call किया वहां पे एक ये ad जो देख रखा आप लोगों ने वही वाला चाहिए मेरे को।"
    },
    {
      "i": 12,
      "speaker": "bot",
      "text": "समझ गई।"
    },
    {
      "i": 13,
      "speaker": "bot",
      "text": "आप उसी flavor की बात कर रहे हैं ना?"
    },
    {
      "i": 14,
      "speaker": "bot",
      "text": "बस confirm कर दीजिए कि आपको कौन सा flavor चाहिए?"
    },
    {
      "i": 15,
      "speaker": "caller",
      "text": "अच्छा।"
    },
    {
      "i": 16,
      "speaker": "caller",
      "text": "उसका बाद में एक piece"
    },
    {
      "i": 17,
      "speaker": "bot",
      "text": "बिल्कुल आप समय लीजिए।"
    },
    {
      "i": 18,
      "speaker": "bot",
      "text": "जी क्या आप अभी भी line पर हैं?"
    },
    {
      "i": 19,
      "speaker": "caller",
      "text": "हाँ।"
    },
    {
      "i": 20,
      "speaker": "bot",
      "text": "कोई बात नहीं।"
    },
    {
      "i": 21,
      "speaker": "bot",
      "text": "तो बताइए आपको कौन सा flavor चाहिए?"
    },
    {
      "i": 22,
      "speaker": "caller",
      "text": "अच्छा एक piece आप WhatsApp में WhatsApp में message कर सकते हैं मैं WhatsApp में आपको उसका एक screenshot दे दूंगा ये वाला मेरे को चाहिए एक kilogram का।"
    },
    {
      "i": 23,
      "speaker": "bot",
      "text": "photo आप seller को directly share कर दीजिएगा।"
    },
    {
      "i": 24,
      "speaker": "bot",
      "text": "अभी मेरे पास photo देखने की facility नहीं है।"
    },
    {
      "i": 25,
      "speaker": "bot",
      "text": "बस flavor confirm कर दीजिए please।"
    },
    {
      "i": 26,
      "speaker": "caller",
      "text": "यहां पे तो कुकड़े मसाला लिखा है।"
    },
    {
      "i": 27,
      "speaker": "bot",
      "text": "ठीक है तो आपको packaging size में एक kilogram ही चाहिए ना?"
    },
    {
      "i": 28,
      "speaker": "caller",
      "text": "हाँ आपका redmi side में एक kilogram चाहिए।"
    },
    {
      "i": 29,
      "speaker": "bot",
      "text": "आपको मैं seller details WhatsApp पे भेज दूंगी जिनसे आप details और price discuss कर सकते हैं।"
    }
  ]
}
